// Rezepte (how-to recipes) in the Hilfe tab. The content and the recordings are
// generated by rezepte/tools/build.mjs; this file only displays them.
//
// The gallery stays on the page; a recipe opens in a popup above it. Opening a
// recipe adds a browser history entry (see studio.js), so the back button
// closes the popup – and the gallery is still exactly where it was.
//
// Cards show a still frame and play their recording only while they are on
// screen: forty animations at once would keep the browser busy for nothing.
//
// The Erste-Schritte guides (rezepte/tools/anleitungen.mjs, /anleitungen/
// anleitungen.json) come first, in their own category: recorded in the real
// studio, with videos of every step. They have their own numbers (#01, #02 …),
// so the recipes keep theirs.

// Pixel art is drawn with hard pixels (image-rendering: pixelated) where it is
// shown at its size or bigger. Shrunk – a wide recording in a card, a big one
// on a small screen – hard pixels would drop rows and columns unevenly and look
// ragged: there it gets the class `verkleinert` and is drawn smoothly.
const pixel_fit = (() => {
    if (typeof ResizeObserver !== 'function') return { watch() { }, forget() { } };
    const check = (img) => {
        if (!img.naturalWidth || !img.clientWidth) return;
        const fit = getComputedStyle(img).objectFit;
        const sx = img.clientWidth / img.naturalWidth, sy = img.clientHeight / img.naturalHeight;
        const scale = fit === 'cover' ? Math.max(sx, sy) : fit === 'contain' ? Math.min(sx, sy) : sx;
        img.classList.toggle('verkleinert', scale * (window.devicePixelRatio || 1) < 0.999);
    };
    const observer = new ResizeObserver(entries => entries.forEach(e => check(e.target)));
    return {
        watch(img) {
            img.addEventListener('load', () => check(img));
            observer.observe(img);
            check(img);
        },
        forget(root) {
            for (const img of $(root).find('img')) observer.unobserve(img);
        },
    };
})();

class RecipeGallery {
    constructor(container) {
        this.container = $(container);
        this.recipes = [];
        this.categories = [];
        this.filter = null;
        this.loaded = false;
        this.pending = null;
        this.rendered_filter = undefined;
        this.open_id = null;
        this.observer = typeof IntersectionObserver === 'function' ?
            new IntersectionObserver(entries => this.visibility_changed(entries), { threshold: 0.35 }) : null;
    }

    async load() {
        try {
            // versioned like the scripts; the images inside carry a content hash
            const response = await fetch(`/rezepte/rezepte.json?${window.CACHE_BUSTER || Date.now()}`);
            if (!response.ok) throw new Error(response.statusText);
            const data = await response.json();
            // the guides are optional: without them the recipes are shown as before
            let guides = { anleitungen: [] };
            try {
                const g = await fetch(`/anleitungen/anleitungen.json?${window.CACHE_BUSTER || Date.now()}`);
                if (g.ok) guides = await g.json();
            } catch { }
            const guide_list = (guides.anleitungen ?? []).map(r => ({ ...r, anleitung: true }));
            this.recipes = [...guide_list, ...(data.rezepte ?? [])];
            const kategorien = [...(guide_list.length ? [guides.kategorie ?? guide_list[0].kategorie] : []), ...(data.kategorien ?? [])];
            this.categories = kategorien.filter(c => this.recipes.some(r => r.kategorie === c));
        } catch (e) {
            this.container.empty().append($('<p>').addClass('rezepte-hinweis')
                .text('Die Rezepte konnten nicht geladen werden.'));
            return;
        }
        this.loaded = true;
        const state = this.pending ?? window.pending_recipe_state ?? null;
        this.pending = null;
        if (state) this.restore(state);
        else this.show_gallery(false);
    }

    // Called for browser back/forward and for links like #hilfe/leiter.
    restore(state) {
        if (!this.loaded) { this.pending = state; return; }
        if (state.filter !== undefined) this.filter = state.filter;
        this.render_gallery();
        if (state.recipe && this.recipes.some(r => r.id === state.recipe)) this.show_recipe(state.recipe, false);
        else this.close_popup(false);
    }

    push(state) {
        if (typeof studio_history_push === 'function') studio_history_push({ pane: 'help', ...state });
    }

    // #01, #02, … in gallery order – for orientation ("mach mit Rezept #12 weiter");
    // the guides count on their own, the same way (the label beside says which)
    number(recipe) {
        const same = this.recipes.filter(r => !!r.anleitung === !!recipe.anleitung);
        const n = same.indexOf(recipe) + 1;
        return '#' + String(n).padStart(2, '0');
    }

    folder(recipe) {
        return recipe.anleitung ? '/anleitungen/' : '/rezepte/';
    }

    // The recording (animated WebP; older builds: GIF) with its content hash.
    media_url(recipe) {
        const file = recipe.bild ?? recipe.gif;
        return `${this.folder(recipe)}${file}${recipe.version ? '?' + recipe.version : ''}`;
    }

    // A single frame of the recording (older builds have none: then the recording).
    still_url(recipe) {
        if (!recipe.standbild) return this.media_url(recipe);
        return `${this.folder(recipe)}${recipe.standbild}${recipe.standbild_version ? '?' + recipe.standbild_version : ''}`;
    }

    // The recipe's scene as a game (rezepte/tools: spiele/<id>.json, written by
    // every build). Older builds have no `spiel` entry; in DEVELOPMENT the file
    // may still be there from `npm run studio`.
    scene_url(recipe) {
        if (recipe.anleitung) return null;
        if (recipe.spiel) return `/rezepte/${recipe.spiel}${recipe.spiel_version ? '?' + recipe.spiel_version : ''}`;
        return window.DEVELOPMENT ? `/rezepte/spiele/${encodeURIComponent(recipe.id)}.json?${Date.now()}` : null;
    }

    // Opens the recipe's scene in the studio, so a child can look at how it is
    // built and play with it. It replaces the game in the studio: asks first if
    // that one has unsaved changes. Saving it later makes it an own game
    // (game.save → own_game.js), so the game list never shows changed recipes.
    open_scene(recipe, button) {
        if (button.prop('disabled')) return;
        if (window.collaboration?.code) {
            // Opening another game leaves the live session (after asking).
            window.collaboration.confirm_leave('load', () => this.open_scene(recipe, button));
            return;
        }
        if (game?.has_unsaved_changes?.()) {
            this.ask_before_replacing(() => this.load_scene(recipe, button));
            return;
        }
        this.load_scene(recipe, button);
    }

    ask_before_replacing(proceed) {
        window.recipeReplaceModal ??= new ModalDialog({
            title: 'Dein Spiel ist noch nicht gespeichert',
            width: '460px',
            max_width: '90vw',
            body: `<div class="collab-dialog"><p class="collab-lead">Die Szene aus dem Rezept ersetzt das Spiel, das gerade im Studio offen ist. Was du seit dem letzten Speichern geändert hast, ist dann weg.</p></div>`,
            footer: [
                { type: 'button', label: 'Abbrechen', callback: (self) => self.dismiss() },
                { type: 'button', label: 'Zuerst speichern', callback: (self) => { self.dismiss(); game.save(); } },
                { type: 'button', label: 'Trotzdem öffnen', color: 'green',
                    callback: (self) => { self.dismiss(); window.recipeReplaceModal.proceed?.(); } },
            ],
        });
        window.recipeReplaceModal.proceed = proceed;
        window.recipeReplaceModal.show();
    }

    async load_scene(recipe, button) {
        const url = this.scene_url(recipe);
        if (!url) return;
        const label = button.html();
        button.prop('disabled', true).text('Wird geöffnet …');
        try {
            const response = await fetch(url);
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            const data = await response.json();
            data.parent = null;
            game.data = data;
            game._load();
            game.from_recipe = { id: recipe.id, titel: recipe.titel };
            game.refresh_own_game_button?.();
            $('#game_code_div').hide();

            // Start on the level so the scene is visible immediately.
            // Browser Back returns to the recipe popup.
            const changed = window.studio_show_pane?.('level');
            if (changed && typeof studio_history_push === 'function')
                studio_history_push({ pane: 'level' });
            game.level_editor?.show_level_notice?.(`Das ist die Szene aus „${recipe.titel}“. Schau dich um und probier alles aus – mit T testest du das Level.`, 8000);
        } catch (e) {
            console.error('Rezept-Szene konnte nicht geladen werden:', e);
            window.alert(window.DEVELOPMENT
                ? 'Die Szene fehlt. Bitte unter rezepte/tools „npm run studio“ (oder den Build) ausführen.'
                : 'Die Szene konnte nicht geladen werden. Versuche es noch einmal.');
        } finally {
            button.prop('disabled', false).html(label);
        }
    }

    visibility_changed(entries) {
        for (const entry of entries) {
            const img = entry.target;
            const url = entry.isIntersecting ? img.dataset.animation : img.dataset.still;
            if (url && img.getAttribute('src') !== url) img.setAttribute('src', url);
        }
    }

    card(recipe, extra_class = '', label = null) {
        const card = $('<button>').addClass('rezept-karte').addClass(extra_class).toggleClass('anleitung', !!recipe.anleitung)
            .on('click', () => this.show_recipe(recipe.id));
        // The recording fills the card, anchored at the bottom (see styles.css).
        const img = $('<img>').attr({ src: this.still_url(recipe), alt: recipe.titel, loading: 'lazy', decoding: 'async' })
            .attr('data-still', this.still_url(recipe)).attr('data-animation', this.media_url(recipe));
        $('<div>').addClass('rezept-bild').css('background', recipe.himmel ?? '').append(img).appendTo(card);
        // Cards are wider than the recording and cut from the top; `karte_unten`
        // (a share of the height) moves the cut down, so a tall scene keeps its top.
        if (recipe.karte_unten > 0 && recipe.breite && recipe.hoehe) {
            const card_aspect = extra_class === 'klein' ? 3 : 12 / 5;
            const cut = 1 - (recipe.breite / recipe.hoehe) / card_aspect;   // share of the height that is cut
            if (cut > 0) {
                const p = Math.max(0, Math.min(1, (cut - recipe.karte_unten) / cut));
                img.css('object-position', `center ${(p * 100).toFixed(1)}%`);
            }
        }
        if (this.observer) this.observer.observe(img[0]);
        pixel_fit.watch(img[0]);
        const text = $('<div>').addClass('rezept-text').appendTo(card);
        $('<div>').addClass('rezept-kopf')
            .append($('<span>').addClass('rezept-kategorie')
                .append($('<span>').addClass('rezept-nummer').text(this.number(recipe)))
                .append(document.createTextNode(label ?? recipe.kategorie)))
            .appendTo(text);
        $('<div>').addClass('rezept-titel').text(recipe.titel).appendTo(text);
        if (!label) $('<div>').addClass('rezept-kurz').text(recipe.kurz).appendTo(text);
        return card;
    }

    // The gallery is only rebuilt when the filter changes: its scroll position stays.
    render_gallery() {
        if (this.rendered_filter === this.filter) return;
        this.rendered_filter = this.filter;
        const self = this;
        for (const img of this.container.find('.rezept-bild img')) this.observer?.unobserve(img);
        pixel_fit.forget(this.container);
        this.container.empty();
        const chips = $('<div>').addClass('rezept-filter').appendTo(this.container);
        for (const category of [null, ...this.categories]) {
            $('<button>').addClass('rezept-chip').toggleClass('active', this.filter === category)
                .text(category ?? 'Alle')
                .on('click', () => {
                    self.filter = category;
                    // A filter is not a new page: remember it without a new history entry.
                    history.replaceState({ pane: 'help', filter: category }, '', window.location.href);
                    self.render_gallery();
                })
                .appendTo(chips);
        }
        // Two parts, clearly apart: the guides (how the studio works) and the
        // recipes (ideas to build). A category shows only its own part.
        const guides = this.recipes.filter(r => r.anleitung && (!this.filter || r.kategorie === this.filter));
        const recipes = this.recipes.filter(r => !r.anleitung && (!this.filter || r.kategorie === this.filter));
        const section = (cls, title, lead, list) => {
            const part = $('<section>').addClass(`rezept-teil ${cls}`).appendTo(this.container);
            $('<h2>').addClass('rezepte-ueberschrift').text(title).appendTo(part);
            $('<p>').addClass('rezept-teil-lead').text(lead).appendTo(part);
            const grid = $('<div>').addClass('rezept-galerie').appendTo(part);
            for (const recipe of list) this.card(recipe).appendTo(grid);
        };
        if (guides.length)
            section('rezept-teil-anleitungen', 'Erste Schritte',
                'So funktioniert das Studio – Schritt für Schritt, mit Videos aus dem Studio. Fang am besten mit #01 an.', guides);
        if (guides.length && recipes.length)
            $('<div>').addClass('rezept-trenner').attr('role', 'separator').appendTo(this.container);
        if (recipes.length)
            section('rezept-teil-rezepte', 'Rezepte',
                'Kleine Anleitungen zum Nachbauen. Jede Animation wurde mit dem echten Spiel aufgenommen – so sieht es auch bei dir aus.', recipes);
    }

    show_gallery(push = true) {
        if (push) this.push({ filter: this.filter });
        this.render_gallery();
        this.close_popup(false);
    }

    popup() {
        if (this.popup_el) return this.popup_el;
        const overlay = $('<div>').addClass('rezept-popup').attr({ role: 'dialog', 'aria-modal': 'true' }).hide();
        const dialog = $('<div>').addClass('rezept-dialog').appendTo(overlay);
        // outside the scrolling part: it stays in the corner while the recipe scrolls
        $('<button>').addClass('rezept-schliessen').attr({ title: 'Schließen (Esc)', 'aria-label': 'Schließen' })
            .html('<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg>')
            .on('click', () => this.close_popup()).appendTo(dialog);
        this.popup_body = $('<div>').addClass('rezept-dialog-inhalt').appendTo(dialog);
        // a click next to the dialog closes it, like the Esc key
        overlay.on('click', (e) => { if (e.target === overlay[0]) this.close_popup(); });
        $(document).on('keydown', (e) => {
            if (e.key === 'Escape' && this.open_id && overlay.is(':visible')) { e.preventDefault(); this.close_popup(); }
        });
        // a link to another recipe or guide in the text (anleitungen.mjs: rezept:<id>)
        this.popup_body.on('click', 'a[data-rezept]', (e) => {
            e.preventDefault();
            this.show_recipe(e.currentTarget.dataset.rezept);
        });
        // inside the Hilfe pane: switching to another tab hides it together with the pane
        overlay.appendTo(document.getElementById('main_div_help') ?? document.body);
        this.popup_el = overlay;
        return overlay;
    }

    close_popup(user = true) {
        if (!this.open_id) return;
        // Opened from the gallery: going back (past every recipe opened in the
        // popup since) is the same as closing – the gallery entry comes back.
        const depth = history.state?.recipe ? Number(history.state.depth) || 0 : 0;
        if (user && depth > 0) { history.go(-depth); return; }
        if (user) this.push({ filter: this.filter });
        this.open_id = null;
        window.anleitung_films?.unmount_all();
        for (const img of this.popup_body?.find('.rezept-bild img') ?? []) this.observer?.unobserve(img);
        if (this.popup_body) pixel_fit.forget(this.popup_body);
        this.popup_body?.empty();
        this.popup_el?.hide();
        this.popup_el?.find('.rezept-dialog').removeClass('anleitung');
        $('#main_div_help').removeClass('rezept-offen');
    }

    show_recipe(id, push = true) {
        const index = this.recipes.findIndex(r => r.id === id);
        const recipe = this.recipes[index];
        if (!recipe) return this.show_gallery(push);
        // from the gallery (or from recipe to recipe inside the popup): a new history entry
        if (push) {
            // how many recipe entries lie on top of the gallery entry (0: opened by a link)
            const depth = this.open_id ? (Number(history.state?.depth) || 0) + (history.state?.depth ? 1 : 0) : 1;
            this.push({ recipe: id, filter: this.filter, depth });
        }
        this.open_id = id;
        const overlay = this.popup();
        for (const img of this.popup_body.find('.rezept-bild img')) this.observer?.unobserve(img);
        window.anleitung_films?.unmount_all();
        pixel_fit.forget(this.popup_body);
        this.popup_body.empty();
        const article = $('<article>').addClass('rezept').appendTo(this.popup_body);
        $('<div>').addClass('rezept-kopf')
            .append($('<span>').addClass('rezept-kategorie')
                .append($('<span>').addClass('rezept-nummer').text(this.number(recipe)))
                .append(document.createTextNode(recipe.kategorie)))
            .appendTo(article);
        $('<h2>').text(recipe.titel).appendTo(article);
        $('<p>').addClass('rezept-lead').text(recipe.kurz).appendTo(article);
        // a guide is wider (its videos show the studio) and has its pictures in the text
        overlay.find('.rezept-dialog').toggleClass('anleitung', !!recipe.anleitung);
        const stage = $('<figure>').addClass('rezept-buehne').appendTo(article);
        // Right above the recording (big recordings fill the screen): open
        // exactly this scene in the studio.
        if (this.scene_url(recipe)) {
            const bar = $('<figcaption>').addClass('rezept-ausprobieren').appendTo(stage);
            $('<span>').addClass('rezept-ausprobieren-text')
                .append($('<b>').text('Selbst ausprobieren: '))
                .append(document.createTextNode('Öffne diese Szene im Studio und schau nach, wie sie gebaut ist.'))
                .appendTo(bar);
            $('<button>').attr('type', 'button').addClass('rezept-ausprobieren-knopf')
                .html('<i class="fa fa-wrench"></i> Szene öffnen')
                .on('click', (e) => this.open_scene(recipe, $(e.currentTarget)))
                .appendTo(bar);
        }
        if (recipe.anleitung) stage.remove();
        else $('<img>').addClass('rezept-hauptbild').attr({ src: this.media_url(recipe), alt: recipe.titel,
            width: recipe.breite, height: recipe.hoehe }).appendTo(stage);
        // Generated at build time from the Markdown sources in rezepte/texte.
        $('<div>').addClass('rezept-inhalt').html(recipe.html).appendTo(article);
        const more = $('<div>').addClass('rezept-weiter').appendTo(this.popup_body);
        for (const [delta, label, guide_label] of [[-1, 'Vorheriges Rezept', 'Vorherige Anleitung'], [1, 'Nächstes Rezept', 'Nächste Anleitung']]) {
            const other = this.recipes[index + delta];
            if (!other) { $('<span>').appendTo(more); continue; }
            this.card(other, 'klein', other.anleitung ? guide_label : label).appendTo(more);
        }
        $('#main_div_help').addClass('rezept-offen');
        overlay.show();
        this.popup_body.scrollTop(0);
        // shrunk pictures smooth, the others with hard pixels (the cards below watch their own)
        for (const img of article.find('img')) pixel_fit.watch(img);
        // a guide's films (anleitung_film.js): they start once they are in view
        window.anleitung_films?.mount(article[0]);
    }
}

document.addEventListener('DOMContentLoaded', () => {
    const container = document.getElementById('rezepte');
    if (!container) return;
    window.recipe_gallery = new RecipeGallery(container);
    window.recipe_gallery.load();
});
